using System.Security.Claims;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using SoodalLife.Api.Domain.Entities;
using SoodalLife.Api.Features.Authentication;
using SoodalLife.Api.Features.Matching;
using SoodalLife.Api.Features.RelationshipBlocks;
using SoodalLife.Api.Infrastructure.Persistence;
using SoodalLife.Api.Infrastructure.Security;

namespace SoodalLife.Api.Features.Interior;

public sealed class InteriorProjectService(SoodalLifeDbContext db,ProviderTradingEligibilityService eligibility,IPrivacyContract privacyContract,IUserRelationshipBlockPolicy relationshipBlocks)
{
    public async Task<IReadOnlyList<InteriorServiceResponse>> Services(CancellationToken token)=>await(from service in db.ServiceCategories.AsNoTracking() join middle in db.ServiceCategories.AsNoTracking() on service.ParentId equals middle.Id join major in db.ServiceCategories.AsNoTracking() on middle.ParentId equals major.Id where service.StatusCode=="ACTIVE"&&(major.Name=="인테리어"||(service.ExternalCode!=null&&service.ExternalCode.StartsWith("INT-"))) orderby middle.SortOrder,service.SortOrder select new InteriorServiceResponse(service.PublicId,service.ExternalCode??string.Empty,major.Name+" > "+middle.Name+" > "+service.Name)).ToListAsync(token);

    public async Task<List<InteriorProjectListItem>> List(string? search,string? status,Guid? provider,Guid? area,DateOnly? from,DateOnly? to,CancellationToken token)
    {
        var query=from project in db.InteriorProjects.AsNoTracking() join request in db.ServiceRequests.AsNoTracking() on project.ServiceRequestId equals request.Id join customer in db.CustomerProfiles.AsNoTracking() on project.CustomerProfileId equals customer.Id join service in db.ServiceCategories.AsNoTracking() on project.ServiceCategoryId equals service.Id join region in db.AdministrativeAreas.AsNoTracking() on request.AdministrativeAreaId equals region.Id select new{project,request,customer,service,region};
        if(!string.IsNullOrWhiteSpace(status))query=query.Where(x=>x.project.StatusCode==status);if(provider.HasValue)query=query.Where(x=>db.ProviderProfiles.Any(p=>p.PublicId==provider&&(p.Id==x.project.SelectedSiteVisitProviderId||p.Id==x.project.SelectedContractorProviderId)));if(area.HasValue)query=query.Where(x=>x.region.PublicId==area);if(from.HasValue)query=query.Where(x=>x.project.ProjectStartDate>=from);if(to.HasValue)query=query.Where(x=>x.project.ProjectStartDate<=to);if(!string.IsNullOrWhiteSpace(search)){var s=search.Trim();query=query.Where(x=>x.customer.DisplayName.Contains(s)||x.service.Name.Contains(s)||x.project.PublicId.ToString().Contains(s));}
        var rows=await query.OrderByDescending(x=>x.project.UpdatedAt).ToListAsync(token);var result=new List<InteriorProjectListItem>();foreach(var x in rows){var site=x.project.SelectedSiteVisitProviderId.HasValue?await db.ProviderProfiles.Where(p=>p.Id==x.project.SelectedSiteVisitProviderId).Select(p=>p.BusinessName).SingleAsync(token):null;var contractor=x.project.SelectedContractorProviderId.HasValue?await db.ProviderProfiles.Where(p=>p.Id==x.project.SelectedContractorProviderId).Select(p=>p.BusinessName).SingleAsync(token):null;var contract=await db.InteriorContracts.AsNoTracking().Where(c=>c.InteriorProjectId==x.project.Id).OrderByDescending(c=>c.ContractVersion).Select(c=>(decimal?)c.ContractAmount).FirstOrDefaultAsync(token);var stages=await db.InteriorWorkStages.AsNoTracking().Where(v=>v.InteriorProjectId==x.project.Id).Select(v=>v.ProgressPercent).ToListAsync(token);result.Add(new(x.project.PublicId,Number(x.project.PublicId),x.customer.DisplayName,x.service.Name,x.region.AreaName,x.project.StatusCode,site,contractor,contract,x.project.ProjectStartDate,x.project.ExpectedCompletionDate,stages.Count==0?0:(int)Math.Round(stages.Average()),await db.AfterServiceCases.AnyAsync(a=>a.TransactionId!=null&&db.Transactions.Any(t=>t.Id==a.TransactionId&&t.ServiceRequestId==x.project.ServiceRequestId),token),await db.DisputeCases.AnyAsync(d=>d.InteriorProjectId==x.project.Id,token),x.project.UpdatedAt));}return result;
    }

    public async Task<InteriorProjectDetail> Create(CreateInteriorProjectRequest input,Guid actor,CancellationToken token)
    {
        var user=await UserId(actor,token);var existingEvent=await db.InteriorProjectEvents.AsNoTracking().SingleOrDefaultAsync(e=>e.IdempotencyKey==input.IdempotencyKey,token);if(existingEvent!=null)return await DetailById(existingEvent.InteriorProjectId,token);
        var row=await(from request in db.ServiceRequests join service in db.ServiceCategories on request.CategoryId equals service.Id join middle in db.ServiceCategories on service.ParentId equals middle.Id join major in db.ServiceCategories on middle.ParentId equals major.Id where request.PublicId==input.ServiceRequestId select new{request,service,major}).SingleOrDefaultAsync(token)??throw NotFound("REQUEST_NOT_FOUND","요청을 찾을 수 없습니다.");if(row.major.Name!="인테리어"&&!(row.service.ExternalCode?.StartsWith("INT-")??false))throw Conflict("INTERIOR_CATEGORY_REQUIRED","인테리어 서비스 요청만 프로젝트로 생성할 수 있습니다.");var existing=await db.InteriorProjects.SingleOrDefaultAsync(p=>p.ServiceRequestId==row.request.Id,token);if(existing!=null)return await DetailById(existing.Id,token);
        var now=DateTime.UtcNow;var project=new InteriorProject{ServiceRequestId=row.request.Id,CustomerProfileId=row.request.CustomerProfileId,ServiceCategoryId=row.request.CategoryId,StatusCode="CONSULTATION",FeeAssessmentStatusCode="PENDING_SELECTION",CreatedAt=now,CreatedByUserId=user,UpdatedAt=now,UpdatedByUserId=user};db.InteriorProjects.Add(project);await db.SaveChangesAsync(token);await Record(project,"PROJECT_CREATED",input.IdempotencyKey,user,new{requestId=input.ServiceRequestId},token);await Audit(user,"INTERIOR_PROJECT_CREATED",project.PublicId,null,new{project.StatusCode},token);return await DetailById(project.Id,token);
    }

    public async Task<InteriorProjectDetail> Detail(Guid id,CancellationToken token){var internalId=await db.InteriorProjects.Where(x=>x.PublicId==id).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token)??throw NotFound("INTERIOR_PROJECT_NOT_FOUND","인테리어 프로젝트를 찾을 수 없습니다.");return await DetailById(internalId,token);}

    public async Task<InteriorSiteVisitResponse> AddSiteVisit(Guid projectId,CreateInteriorSiteVisitRequest input,Guid actor,CancellationToken token)
    {
        var user=await UserId(actor,token);var project=await Project(projectId,token);var provider=await db.ProviderProfiles.SingleOrDefaultAsync(x=>x.PublicId==input.ProviderId,token)??throw NotFound("PROVIDER_NOT_FOUND","전문가를 찾을 수 없습니다.");await relationshipBlocks.EnsureAllowedAsync(project.CustomerProfileId,provider.Id,token);var request=await db.ServiceRequests.AsNoTracking().SingleAsync(x=>x.Id==project.ServiceRequestId,token);var check=await eligibility.EvaluateAsync(provider.Id,project.ServiceCategoryId,request.AdministrativeAreaId??throw Conflict("REQUEST_AREA_REQUIRED","서비스 지역이 없는 요청은 실측 전문가를 지정할 수 없습니다."),token);if(!check.IsEligible)throw Conflict(check.ReasonCode??"PROVIDER_NOT_ELIGIBLE","서비스 승인·지역·요건을 충족한 전문가만 실측 후보로 지정할 수 있습니다.");if(input.ScheduledEndAt.HasValue&&input.ScheduledEndAt<=input.ScheduledStartAt)throw Conflict("INVALID_SITE_VISIT_PERIOD","실측 종료시간은 시작시간보다 늦어야 합니다.");var now=DateTime.UtcNow;var visit=new InteriorSiteVisit{InteriorProjectId=project.Id,ProviderProfileId=provider.Id,StatusCode="PROPOSED",ProposedAt=now,ScheduledStartAt=input.ScheduledStartAt,ScheduledEndAt=input.ScheduledEndAt,AccessConditionText=input.AccessConditionText,CreatedAt=now,CreatedByUserId=user,UpdatedAt=now,UpdatedByUserId=user};db.InteriorSiteVisits.Add(visit);project.StatusCode="SITE_VISIT_SELECTION";project.UpdatedAt=now;project.UpdatedByUserId=user;await db.SaveChangesAsync(token);await Record(project,"SITE_VISIT_PROPOSED",input.IdempotencyKey,user,new{visitId=visit.PublicId,providerId=provider.PublicId},token);return Visit(visit,provider.PublicId,provider.BusinessName);
    }

    public async Task<InteriorSiteVisitResponse> ConfirmSiteVisit(Guid projectId,Guid visitId,ConfirmInteriorSiteVisitRequest input,Guid actor,CancellationToken token)
    {
        var user=await UserId(actor,token);var project=await Project(projectId,token);var visit=await db.InteriorSiteVisits.SingleOrDefaultAsync(x=>x.PublicId==visitId&&x.InteriorProjectId==project.Id,token)??throw NotFound("SITE_VISIT_NOT_FOUND","실측 일정을 찾을 수 없습니다.");if(visit.StatusCode!="PROPOSED"&&visit.StatusCode!="CONFIRMED")throw Conflict("SITE_VISIT_STATE_CONFLICT","제안 상태의 실측 일정만 확정할 수 있습니다.");var now=DateTime.UtcNow;visit.StatusCode="CONFIRMED";visit.ConfirmedAt??=now;visit.UpdatedAt=now;visit.UpdatedByUserId=user;project.SelectedSiteVisitProviderId=visit.ProviderProfileId;project.SiteVisitSelectedAt??=now;project.SiteVisitProviderTrustScoreSnapshot=await CurrentTrust(visit.ProviderProfileId,token);project.StatusCode="SITE_VISIT_SCHEDULED";project.UpdatedAt=now;project.UpdatedByUserId=user;await EnsureParticipant(project,visit.ProviderProfileId,"SITE_SURVEY",true,"현장 실측",user,now,token);await db.SaveChangesAsync(token);await Record(project,"SITE_VISIT_CONFIRMED",input.IdempotencyKey,user,new{visitId},token);await Audit(user,"INTERIOR_SITE_VISIT_CONFIRMED",project.PublicId,null,new{visitId},token);var provider=await db.ProviderProfiles.Where(x=>x.Id==visit.ProviderProfileId).Select(x=>new{x.PublicId,x.BusinessName}).SingleAsync(token);return Visit(visit,provider.PublicId,provider.BusinessName);
    }

    public async Task<InteriorSiteVisitResponse> CompleteSiteVisit(Guid projectId,Guid visitId,CompleteInteriorSiteVisitRequest input,Guid actor,CancellationToken token)
    {
        var user=await UserId(actor,token);var project=await Project(projectId,token);var visit=await db.InteriorSiteVisits.SingleOrDefaultAsync(x=>x.PublicId==visitId&&x.InteriorProjectId==project.Id,token)??throw NotFound("SITE_VISIT_NOT_FOUND","실측 일정을 찾을 수 없습니다.");if(visit.StatusCode!="CONFIRMED")throw Conflict("SITE_VISIT_NOT_CONFIRMED","확정된 실측만 완료할 수 있습니다.");var now=DateTime.UtcNow;foreach(var value in input.Measurements??[]){db.InteriorSiteVisitMeasurements.Add(new(){SiteVisitId=visit.Id,MeasurementKey=value.Key.Trim(),MeasurementValue=value.Value,MeasurementText=value.Text,UnitText=value.Unit,LocationText=value.Location,NoteText=value.Note,AdditionalDataJson=value.AdditionalDataJson,CreatedAt=now,CreatedByUserId=user});}await LinkFiles(input.FileIds,visit.Id,"SITE_VISIT",user,token);visit.StatusCode="COMPLETED";visit.VisitedAt??=now;visit.CompletedAt=now;visit.MeasurementSummaryText=input.MeasurementSummary;visit.ConstraintText=input.Constraint;visit.RiskNoteText=input.RiskNote;visit.UpdatedAt=now;visit.UpdatedByUserId=user;project.StatusCode="SITE_VISIT_COMPLETED";project.UpdatedAt=now;project.UpdatedByUserId=user;await db.SaveChangesAsync(token);await Record(project,"SITE_VISIT_COMPLETED",input.IdempotencyKey,user,new{visitId},token);var provider=await db.ProviderProfiles.Where(x=>x.Id==visit.ProviderProfileId).Select(x=>new{x.PublicId,x.BusinessName}).SingleAsync(token);return Visit(visit,provider.PublicId,provider.BusinessName);
    }

    public async Task<InteriorDesignResponse> AddDesign(Guid projectId,CreateInteriorDesignRequest input,Guid actor,CancellationToken token){var user=await UserId(actor,token);var project=await Project(projectId,token);if(project.SelectedContractorProviderId.HasValue)throw Conflict("INTERIOR_DESIGN_SELECTION_LOCKED","최종 전문가 선택 후에는 선택 근거가 된 설계·견적을 변경할 수 없습니다.");var version=await db.InteriorDesignVersions.Where(x=>x.InteriorProjectId==project.Id).MaxAsync(x=>(int?)x.VersionNo,token)??0;var now=DateTime.UtcNow;var design=new InteriorDesignVersion{InteriorProjectId=project.Id,VersionNo=version+1,Title=input.Title.Trim(),Description=input.Description,StatusCode="DRAFT",CreatedAt=now,CreatedByUserId=user,UpdatedAt=now,UpdatedByUserId=user};db.InteriorDesignVersions.Add(design);await db.SaveChangesAsync(token);foreach(var file in await Files(input.FileIds,token))db.InteriorDesignFiles.Add(new(){DesignVersionId=design.Id,FileId=file.Id,PurposeCode="DESIGN",CreatedAt=now,CreatedByUserId=user});project.StatusCode="ESTIMATE_IN_PROGRESS";await db.SaveChangesAsync(token);await Record(project,"DESIGN_UPDATED",input.IdempotencyKey,user,new{designId=design.PublicId,design.VersionNo},token);return new(design.PublicId,design.VersionNo,design.Title,design.Description,design.StatusCode,design.CustomerApprovedAt);}

    public async Task<InteriorContractResponse> CreateContract(Guid projectId,CreateInteriorContractRequest input,Guid actor,CancellationToken token)
    {
        var user=await UserId(actor,token);var project=await Project(projectId,token);var provider=await db.ProviderProfiles.SingleOrDefaultAsync(x=>x.PublicId==input.ProviderId,token)??throw NotFound("PROVIDER_NOT_FOUND","전문가를 찾을 수 없습니다.");var revision=await(from r in db.QuoteRevisions join q in db.Quotes on r.QuoteId equals q.Id where r.PublicId==input.QuoteRevisionId&&q.ServiceRequestId==project.ServiceRequestId&&q.ProviderProfileId==provider.Id select new{r,q}).SingleOrDefaultAsync(token)??throw Conflict("QUOTE_REVISION_MISMATCH","프로젝트와 전문가에 연결된 견적 차수만 계약에 사용할 수 있습니다.");if(project.SelectedContractorProviderId!=provider.Id||project.CurrentQuoteRevisionId!=revision.r.Id||!project.ContractorSelectedAt.HasValue)throw Conflict("CUSTOMER_PROVIDER_SELECTION_REQUIRED","고객이 최종 선택한 전문가와 견적 Version만 계약으로 전환할 수 있습니다.");if(project.StatusCode!="ESTIMATE_READY"||project.CurrentContractId.HasValue)throw Conflict("INTERIOR_CONTRACT_STATE_CONFLICT","현재 프로젝트 단계에서는 계약을 생성할 수 없습니다.");if(input.ContractAmount!=revision.r.TotalAmount||input.CurrencyCode!=revision.r.CurrencyCode)throw Conflict("INTERIOR_SELECTED_QUOTE_TERMS_MISMATCH","계약 최초 금액과 통화는 고객이 선택한 견적과 일치해야 합니다.");if(input.ContractAmount<0||input.PlannedCompletionDate<input.PlannedStartDate)throw Conflict("INVALID_CONTRACT","계약 금액과 공사기간을 확인해 주세요.");var now=DateTime.UtcNow;var version=(await db.InteriorContracts.Where(x=>x.InteriorProjectId==project.Id).MaxAsync(x=>(int?)x.ContractVersion,token)??0)+1;var contract=new InteriorContract{InteriorProjectId=project.Id,CustomerProfileId=project.CustomerProfileId,ProviderProfileId=provider.Id,ContractVersion=version,SelectedQuoteRevisionId=revision.r.Id,ContractAmount=input.ContractAmount,CurrencyCode=input.CurrencyCode,ScopeSnapshotJson=input.ScopeSnapshotJson,QuoteSnapshotJson=JsonSerializer.Serialize(new{revisionId=revision.r.PublicId,revision.r.RevisionNo,revision.r.TotalAmount,revision.r.CurrencyCode}),ScheduleSnapshotJson=input.ScheduleSnapshotJson,WarrantySnapshotJson=input.WarrantySnapshotJson,ProviderTrustScoreSnapshot=project.ContractorTrustScoreSnapshot,PlannedStartDate=input.PlannedStartDate,PlannedCompletionDate=input.PlannedCompletionDate,CreatedAt=now,CreatedByUserId=user,UpdatedAt=now,UpdatedByUserId=user};db.InteriorContracts.Add(contract);await db.SaveChangesAsync(token);foreach(var plan in input.PaymentPlans??[])db.InteriorPaymentPlans.Add(new(){InteriorContractId=contract.Id,SequenceNo=plan.SequenceNo,PaymentName=plan.Name.Trim(),PlannedAmount=plan.Amount,PlannedDueDate=plan.DueDate,ConditionText=plan.Condition,CreatedAt=now,CreatedByUserId=user,UpdatedAt=now,UpdatedByUserId=user});db.InteriorContractVersions.Add(new(){InteriorContractId=contract.Id,VersionNo=version,ContractAmount=contract.ContractAmount,CurrencyCode=contract.CurrencyCode,ScopeSnapshotJson=contract.ScopeSnapshotJson,ScheduleSnapshotJson=contract.ScheduleSnapshotJson,PaymentPlanSnapshotJson=JsonSerializer.Serialize(input.PaymentPlans??[]),WarrantySnapshotJson=contract.WarrantySnapshotJson,CreatedAt=now,CreatedByUserId=user});project.CurrentContractId=contract.Id;project.StatusCode="CONTRACT_PENDING";project.UpdatedAt=now;project.UpdatedByUserId=user;await EnsureParticipant(project,provider.Id,"PRIMARY_CONTRACTOR",true,"프로젝트 대표 시공",user,project.ContractorSelectedAt.Value,token);await db.SaveChangesAsync(token);await Record(project,"CONTRACT_CREATED",input.IdempotencyKey,user,new{contractId=contract.PublicId,providerId=provider.PublicId,quoteRevisionId=revision.r.PublicId},token);return Contract(contract,provider.BusinessName);
    }

    public async Task<InteriorContractResponse> AgreeContract(Guid id,AgreeInteriorContractRequest input,ClaimsPrincipal principal,CancellationToken token)
    {
        var identity=await Identity(principal,token);var contract=await db.InteriorContracts.SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw NotFound("CONTRACT_NOT_FOUND","계약을 찾을 수 없습니다.");var project=await db.InteriorProjects.SingleAsync(x=>x.Id==contract.InteriorProjectId,token);var now=DateTime.UtcNow;if(identity.CustomerProfileId==contract.CustomerProfileId)contract.CustomerAgreedAt??=now;else if(identity.ProviderProfileId==contract.ProviderProfileId)contract.ProviderAgreedAt??=now;else throw NotFound("CONTRACT_NOT_FOUND","계약을 찾을 수 없습니다.");if(contract.CustomerAgreedAt.HasValue&&contract.ProviderAgreedAt.HasValue){contract.StatusCode="EFFECTIVE";contract.EffectiveAt??=now;project.StatusCode="CONTRACTED";}contract.UpdatedAt=now;contract.UpdatedByUserId=identity.UserId;project.UpdatedAt=now;project.UpdatedByUserId=identity.UserId;await db.SaveChangesAsync(token);await Record(project,"CONTRACT_AGREED",input.IdempotencyKey,identity.UserId,new{contractId=id,contract.CustomerAgreedAt,contract.ProviderAgreedAt},token);return Contract(contract,await db.ProviderProfiles.Where(x=>x.Id==contract.ProviderProfileId).Select(x=>x.BusinessName).SingleAsync(token));
    }

    public async Task<Guid> ConfirmPayment(Guid planId,ConfirmInteriorPaymentRequest input,ClaimsPrincipal principal,CancellationToken token)
    {
        var identity=await Identity(principal,token);
        var plan=await db.InteriorPaymentPlans.SingleOrDefaultAsync(x=>x.PublicId==planId,token)??throw NotFound("PAYMENT_PLAN_NOT_FOUND","지급계획을 찾을 수 없습니다.");
        var contract=await db.InteriorContracts.SingleAsync(x=>x.Id==plan.InteriorContractId,token);
        var isCustomer=identity.CustomerProfileId==contract.CustomerProfileId;
        var isProvider=identity.ProviderProfileId==contract.ProviderProfileId;
        if(!isCustomer&&!isProvider)throw NotFound("PAYMENT_PLAN_NOT_FOUND","지급계획을 찾을 수 없습니다.");
        if(contract.StatusCode!="EFFECTIVE")throw Conflict("INTERIOR_CONTRACT_NOT_EFFECTIVE","양쪽이 최종 확인한 계약의 지급내역만 기록할 수 있습니다.");
        var type=input.ConfirmationTypeCode.Trim().ToUpperInvariant();
        if((isCustomer&&type!="CUSTOMER_DIRECT_PAYMENT")||(isProvider&&type!="PROVIDER_REPORTED"))
            throw Conflict("INTERIOR_PAYMENT_CONFIRMATION_TYPE_INVALID","고객은 직접 지급 확인, 전문가는 수령 확인으로 기록해 주세요.");
        if(input.Amount!=plan.PlannedAmount)
            throw Conflict("INTERIOR_PAYMENT_AMOUNT_MISMATCH","확인 금액은 계약서의 해당 지급계획 금액과 일치해야 합니다.");
        if(input.ConfirmedAt>DateTime.UtcNow.AddMinutes(10))
            throw Conflict("INTERIOR_PAYMENT_DATE_INVALID","미래의 지급·수령 내역은 확인할 수 없습니다.");
        var existing=await db.InteriorProjectEvents.AsNoTracking().AnyAsync(x=>x.IdempotencyKey==input.IdempotencyKey,token);
        if(existing)return await db.InteriorPaymentConfirmations.Where(x=>x.PaymentPlanId==plan.Id&&x.ConfirmedByUserId==identity.UserId&&x.ConfirmationTypeCode==type).Select(x=>x.PublicId).SingleAsync(token);
        if(await db.InteriorPaymentConfirmations.AnyAsync(x=>x.PaymentPlanId==plan.Id&&x.ConfirmedByUserId==identity.UserId&&x.ConfirmationTypeCode==type,token))
            throw Conflict("INTERIOR_PAYMENT_ALREADY_CONFIRMED","이미 같은 지급계획을 확인했습니다.");
        long? file=null;
        if(input.EvidenceFileId.HasValue)file=(await db.Files.SingleOrDefaultAsync(x=>x.PublicId==input.EvidenceFileId&&x.StatusCode=="ACTIVE"&&x.UploadedByUserId==identity.UserId,token)??throw NotFound("FILE_NOT_FOUND","본인이 등록한 활성 증빙파일을 찾을 수 없습니다.")).Id;
        var confirmation=new InteriorPaymentConfirmation{PaymentPlanId=plan.Id,ConfirmedByUserId=identity.UserId,ConfirmationTypeCode=type,ConfirmedAmount=input.Amount,ConfirmedAt=input.ConfirmedAt,EvidenceFileId=file,NoteText=input.Note,CreatedAt=DateTime.UtcNow};
        db.InteriorPaymentConfirmations.Add(confirmation);
        await db.SaveChangesAsync(token);
        var types=await db.InteriorPaymentConfirmations.Where(x=>x.PaymentPlanId==plan.Id).Select(x=>x.ConfirmationTypeCode).Distinct().ToListAsync(token);
        if(types.Contains("CUSTOMER_DIRECT_PAYMENT")&&types.Contains("PROVIDER_REPORTED")){plan.StatusCode="CONFIRMED";plan.UpdatedAt=DateTime.UtcNow;plan.UpdatedByUserId=identity.UserId;}
        var project=await db.InteriorProjects.SingleAsync(x=>x.Id==contract.InteriorProjectId,token);
        await Record(project,"PAYMENT_CONFIRMED",input.IdempotencyKey,identity.UserId,new{paymentPlanId=planId,confirmationId=confirmation.PublicId,input.Amount,confirmationTypeCode=type},token);
        return confirmation.PublicId;
    }

    public async Task<InteriorWorkStageResponse> AddStage(Guid projectId,CreateInteriorWorkStageRequest input,Guid actor,CancellationToken token){var user=await UserId(actor,token);var project=await Project(projectId,token);if(input.PlannedEndDate<input.PlannedStartDate)throw Conflict("INVALID_STAGE_PERIOD","공정 종료일은 시작일보다 빠를 수 없습니다.");var now=DateTime.UtcNow;var stage=new InteriorWorkStage{InteriorProjectId=project.Id,SequenceNo=input.SequenceNo,StageName=input.Name.Trim(),PlannedStartDate=input.PlannedStartDate,PlannedEndDate=input.PlannedEndDate,CreatedAt=now,CreatedByUserId=user,UpdatedAt=now,UpdatedByUserId=user};db.InteriorWorkStages.Add(stage);if(project.StatusCode=="CONTRACTED")project.StatusCode="CONSTRUCTION";await db.SaveChangesAsync(token);await Record(project,"STAGE_CREATED",input.IdempotencyKey,user,new{stageId=stage.PublicId},token);return Stage(stage,0,0);}
    public async Task<InteriorParticipantResponse> AddParticipant(Guid projectId,AddInteriorParticipantRequest input,Guid actor,CancellationToken token){var role=Role(input.RoleCode);if(input.EffectiveTo.HasValue&&input.EffectiveTo<input.EffectiveFrom)throw Conflict("INTERIOR_PARTICIPANT_PERIOD_INVALID","참여 종료일시는 시작일시보다 빠를 수 없습니다.");var user=await UserId(actor,token);var project=await Project(projectId,token);var provider=await db.ProviderProfiles.SingleOrDefaultAsync(x=>x.PublicId==input.ProviderId&&x.ApprovalStatusCode=="APPROVED"&&x.ActivityStatusCode=="ACTIVE",token)??throw NotFound("PROVIDER_NOT_FOUND","활성 승인 전문가를 찾을 수 없습니다.");var existing=await db.InteriorProjectParticipants.SingleOrDefaultAsync(x=>x.InteriorProjectId==project.Id&&x.ProviderProfileId==provider.Id&&x.RoleCode==role,token);if(existing is not null)return Participant(existing,provider);var now=DateTime.UtcNow;var item=new InteriorProjectParticipant{InteriorProjectId=project.Id,ProviderProfileId=provider.Id,RoleCode=role,EffectiveFrom=input.EffectiveFrom,EffectiveTo=input.EffectiveTo,StatusCode="ACTIVE",IsPrimary=input.IsPrimary,ScopeText=Clean(input.ScopeText),CreatedAt=now,CreatedByUserId=user,UpdatedAt=now,UpdatedByUserId=user};db.InteriorProjectParticipants.Add(item);await db.SaveChangesAsync(token);await Record(project,"PARTICIPANT_ADDED",input.IdempotencyKey,user,new{participantId=item.PublicId,providerId=provider.PublicId,role},token);await Audit(user,"INTERIOR_PARTICIPANT_ADDED",project.PublicId,null,new{participantId=item.PublicId,role},token);return Participant(item,provider);}
    public async Task<Guid> AssignStage(Guid stageId,AssignInteriorStageRequest input,Guid actor,CancellationToken token){var user=await UserId(actor,token);var stage=await db.InteriorWorkStages.SingleOrDefaultAsync(x=>x.PublicId==stageId,token)??throw NotFound("WORK_STAGE_NOT_FOUND","공정을 찾을 수 없습니다.");var participant=await db.InteriorProjectParticipants.SingleOrDefaultAsync(x=>x.PublicId==input.ParticipantId&&x.InteriorProjectId==stage.InteriorProjectId&&(x.RoleCode=="PRIMARY_CONTRACTOR"||x.RoleCode=="TRADE_CONTRACTOR"),token)??throw Conflict("INTERIOR_STAGE_PARTICIPANT_INVALID","시공 역할 참여자만 공정에 배정할 수 있습니다.");if(input.EffectiveTo.HasValue&&input.EffectiveTo<input.EffectiveFrom)throw Conflict("INTERIOR_STAGE_ASSIGNMENT_PERIOD_INVALID","공정 배정 종료일시는 시작일시보다 빠를 수 없습니다.");var existing=await db.InteriorWorkStageAssignments.SingleOrDefaultAsync(x=>x.WorkStageId==stage.Id&&x.ProjectParticipantId==participant.Id,token);if(existing is not null)return existing.PublicId;var now=DateTime.UtcNow;var item=new InteriorWorkStageAssignment{WorkStageId=stage.Id,ProjectParticipantId=participant.Id,StatusCode="ACTIVE",EffectiveFrom=input.EffectiveFrom,EffectiveTo=input.EffectiveTo,CreatedAt=now,CreatedByUserId=user,UpdatedAt=now,UpdatedByUserId=user};db.InteriorWorkStageAssignments.Add(item);await db.SaveChangesAsync(token);await Record(await db.InteriorProjects.SingleAsync(x=>x.Id==stage.InteriorProjectId,token),"STAGE_ASSIGNED",input.IdempotencyKey,user,new{stageId,participantId=input.ParticipantId},token);return item.PublicId;}
    public async Task<InteriorWorkStageResponse> UpdateStage(Guid stageId,AddInteriorWorkUpdateRequest input,ClaimsPrincipal principal,CancellationToken token){var identity=await Identity(principal,token);var stage=await db.InteriorWorkStages.SingleOrDefaultAsync(x=>x.PublicId==stageId,token)??throw NotFound("WORK_STAGE_NOT_FOUND","공정을 찾을 수 없습니다.");var project=await db.InteriorProjects.SingleAsync(x=>x.Id==stage.InteriorProjectId,token);var now=DateTime.UtcNow;var primary=identity.ProviderProfileId.HasValue&&await db.InteriorProjectParticipants.AsNoTracking().AnyAsync(x=>x.InteriorProjectId==project.Id&&x.ProviderProfileId==identity.ProviderProfileId&&x.RoleCode=="PRIMARY_CONTRACTOR"&&x.StatusCode=="ACTIVE"&&x.EffectiveFrom<=now&&(x.EffectiveTo==null||x.EffectiveTo>now),token);var trade=identity.ProviderProfileId.HasValue&&await(from a in db.InteriorWorkStageAssignments.AsNoTracking() join p in db.InteriorProjectParticipants.AsNoTracking() on a.ProjectParticipantId equals p.Id where a.WorkStageId==stage.Id&&p.ProviderProfileId==identity.ProviderProfileId&&p.RoleCode=="TRADE_CONTRACTOR"&&p.StatusCode=="ACTIVE"&&a.StatusCode=="ACTIVE"&&p.EffectiveFrom<=now&&(p.EffectiveTo==null||p.EffectiveTo>now)&&a.EffectiveFrom<=now&&(a.EffectiveTo==null||a.EffectiveTo>now) select a).AnyAsync(token);if(identity.ProviderProfileId!=project.SelectedContractorProviderId&&!primary&&!trade&&!principal.IsInRole("ADMIN"))throw NotFound("WORK_STAGE_NOT_FOUND","공정을 찾을 수 없습니다.");var update=new InteriorWorkUpdate{WorkStageId=stage.Id,ProgressPercent=input.ProgressPercent,UpdateText=input.UpdateText.Trim(),IssueText=input.IssueText,CreatedAt=now,CreatedByUserId=identity.UserId};db.InteriorWorkUpdates.Add(update);await db.SaveChangesAsync(token);foreach(var file in await Files(input.FileIds,token))db.InteriorWorkUpdateFiles.Add(new(){WorkUpdateId=update.Id,FileId=file.Id,PurposeCode="PROGRESS",CreatedAt=now,CreatedByUserId=identity.UserId});stage.ProgressPercent=input.ProgressPercent;stage.StatusCode=input.ProgressPercent==100?"COMPLETED":input.ProgressPercent>0?"IN_PROGRESS":"PLANNED";stage.ActualStartAt??=input.ProgressPercent>0?now:null;if(input.ProgressPercent==100)stage.ActualEndAt=now;stage.UpdatedAt=now;stage.UpdatedByUserId=identity.UserId;await db.SaveChangesAsync(token);await Record(project,"STAGE_UPDATED",input.IdempotencyKey,identity.UserId,new{stageId,input.ProgressPercent},token);return Stage(stage,await db.InteriorWorkUpdates.CountAsync(x=>x.WorkStageId==stage.Id,token),await db.InteriorStageInspections.CountAsync(x=>x.WorkStageId==stage.Id,token));}
