    public async Task<InteriorChangeResponse> RequestChange(Guid contractId,CreateInteriorChangeRequest input,ClaimsPrincipal principal,CancellationToken token){var identity=await Identity(principal,token);var contract=await db.InteriorContracts.SingleOrDefaultAsync(x=>x.PublicId==contractId,token)??throw NotFound("CONTRACT_NOT_FOUND","계약을 찾을 수 없습니다.");if(identity.CustomerProfileId!=contract.CustomerProfileId&&identity.ProviderProfileId!=contract.ProviderProfileId&&!principal.IsInRole("ADMIN"))throw NotFound("CONTRACT_NOT_FOUND","계약을 찾을 수 없습니다.");var no=(await db.InteriorContractChanges.Where(x=>x.InteriorContractId==contract.Id).MaxAsync(x=>(int?)x.ChangeNo,token)??0)+1;var now=DateTime.UtcNow;var change=new InteriorContractChange{InteriorContractId=contract.Id,ChangeNo=no,RequestedByUserId=identity.UserId,ChangeTypeCode=input.ChangeTypeCode,ReasonText=input.Reason.Trim(),ScopeChangeText=input.ScopeChange.Trim(),AmountDelta=input.AmountDelta,ScheduleImpactDays=input.ScheduleImpactDays,RequestedAt=now,CreatedAt=now,CreatedByUserId=identity.UserId,UpdatedAt=now,UpdatedByUserId=identity.UserId};db.InteriorContractChanges.Add(change);await db.SaveChangesAsync(token);await Record(await db.InteriorProjects.SingleAsync(x=>x.Id==contract.InteriorProjectId,token),"CHANGE_REQUESTED",input.IdempotencyKey,identity.UserId,new{changeId=change.PublicId,input.AmountDelta},token);return Change(change);}
    public async Task<InteriorChangeResponse> DecideChange(Guid id,DecideInteriorChangeRequest input,ClaimsPrincipal principal,CancellationToken token){var identity=await Identity(principal,token);var change=await db.InteriorContractChanges.SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw NotFound("CONTRACT_CHANGE_NOT_FOUND","계약 변경을 찾을 수 없습니다.");var contract=await db.InteriorContracts.SingleAsync(x=>x.Id==change.InteriorContractId,token);if(identity.CustomerProfileId!=contract.CustomerProfileId)throw NotFound("CONTRACT_CHANGE_NOT_FOUND","계약 변경을 찾을 수 없습니다.");if(change.StatusCode!="REQUESTED")throw Conflict("CHANGE_ALREADY_DECIDED","이미 결정된 변경요청입니다.");var now=DateTime.UtcNow;change.StatusCode=input.Approve?"APPROVED":"REJECTED";change.CustomerDecidedAt=now;change.UpdatedAt=now;change.UpdatedByUserId=identity.UserId;if(input.Approve){var next=contract.ContractVersion+1;db.InteriorContractVersions.Add(new(){InteriorContractId=contract.Id,VersionNo=next,SourceContractChangeId=change.Id,ContractAmount=contract.ContractAmount+change.AmountDelta,CurrencyCode=contract.CurrencyCode,ScopeSnapshotJson=JsonSerializer.Serialize(new{previous=contract.ScopeSnapshotJson,change=change.ScopeChangeText}),ScheduleSnapshotJson=JsonSerializer.Serialize(new{previous=contract.ScheduleSnapshotJson,change.ScheduleImpactDays}),PaymentPlanSnapshotJson=JsonSerializer.Serialize(await db.InteriorPaymentPlans.AsNoTracking().Where(x=>x.InteriorContractId==contract.Id).Select(x=>new{x.SequenceNo,x.PaymentName,x.PlannedAmount,x.PlannedDueDate}).ToListAsync(token)),WarrantySnapshotJson=contract.WarrantySnapshotJson,CustomerAgreedAt=now,CreatedAt=now,CreatedByUserId=identity.UserId});contract.ContractVersion=next;contract.ContractAmount+=change.AmountDelta;contract.ScopeSnapshotJson=JsonSerializer.Serialize(new{previous=contract.ScopeSnapshotJson,change=change.ScopeChangeText});contract.UpdatedAt=now;contract.UpdatedByUserId=identity.UserId;}await db.SaveChangesAsync(token);await Record(await db.InteriorProjects.SingleAsync(x=>x.Id==contract.InteriorProjectId,token),input.Approve?"CHANGE_APPROVED":"CHANGE_REJECTED",input.IdempotencyKey,identity.UserId,new{changeId=id},token);return Change(change);}

    public async Task<Guid> LinkDefect(Guid projectId,LinkInteriorDefectRequest input,Guid actor,CancellationToken token){var user=await UserId(actor,token);var project=await Project(projectId,token);var afterService=await db.AfterServiceCases.SingleOrDefaultAsync(x=>x.PublicId==input.AfterServiceCaseId,token)??throw NotFound("AFTER_SERVICE_CASE_NOT_FOUND","A/S 접수 건을 찾을 수 없습니다.");if(afterService.CustomerProfileId!=project.CustomerProfileId||project.SelectedContractorProviderId!=afterService.ProviderProfileId)throw Conflict("AFTER_SERVICE_PROJECT_MISMATCH","해당 프로젝트의 A/S 접수 건만 연결할 수 있습니다.");long? stageId=null;if(input.WorkStageId.HasValue)stageId=await db.InteriorWorkStages.Where(x=>x.PublicId==input.WorkStageId&&x.InteriorProjectId==project.Id).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token)??throw NotFound("WORK_STAGE_NOT_FOUND","해당 프로젝트의 공정을 찾을 수 없습니다.");var existing=await db.InteriorDefects.SingleOrDefaultAsync(x=>x.AfterServiceCaseId==afterService.Id,token);if(existing!=null)return existing.PublicId;var defect=new InteriorDefect{InteriorProjectId=project.Id,AfterServiceCaseId=afterService.Id,WorkStageId=stageId,ContractVersion=input.ContractVersion,DefectLocationText=input.Location.Trim(),DefectDescription=input.Description.Trim(),CreatedAt=DateTime.UtcNow,CreatedByUserId=user};db.InteriorDefects.Add(defect);project.StatusCode="DEFECT_MANAGEMENT";project.UpdatedAt=DateTime.UtcNow;project.UpdatedByUserId=user;await db.SaveChangesAsync(token);await Record(project,"DEFECT_REPORTED",input.IdempotencyKey,user,new{defectId=defect.PublicId,afterServiceCaseId=input.AfterServiceCaseId},token);await Audit(user,"INTERIOR_DEFECT_LINKED",project.PublicId,null,new{defectId=defect.PublicId},token);return defect.PublicId;}

    public async Task<Guid> LinkDispute(Guid projectId,LinkInteriorDisputeRequest input,Guid actor,CancellationToken token){var user=await UserId(actor,token);var project=await Project(projectId,token);var dispute=await db.DisputeCases.SingleOrDefaultAsync(x=>x.PublicId==input.DisputeCaseId,token)??throw NotFound("DISPUTE_CASE_NOT_FOUND","분쟁 건을 찾을 수 없습니다.");var customerUser=await db.CustomerProfiles.Where(x=>x.Id==project.CustomerProfileId).Select(x=>x.UserId).SingleAsync(token);var providerUser=project.SelectedContractorProviderId.HasValue?await db.ProviderProfiles.Where(x=>x.Id==project.SelectedContractorProviderId).Select(x=>(long?)x.UserId).SingleAsync(token):null;var related=(dispute.ApplicantUserId==customerUser&&dispute.CounterpartyUserId==providerUser)||(dispute.CounterpartyUserId==customerUser&&dispute.ApplicantUserId==providerUser);if(!related&&dispute.TransactionId.HasValue)related=await db.Transactions.AnyAsync(x=>x.Id==dispute.TransactionId&&x.ServiceRequestId==project.ServiceRequestId,token);if(!related)throw Conflict("DISPUTE_PROJECT_MISMATCH","해당 프로젝트의 분쟁 건만 연결할 수 있습니다.");long? changeId=null;if(input.ContractChangeId.HasValue)changeId=await(from change in db.InteriorContractChanges join contract in db.InteriorContracts on change.InteriorContractId equals contract.Id where change.PublicId==input.ContractChangeId&&contract.InteriorProjectId==project.Id select(long?)change.Id).SingleOrDefaultAsync(token)??throw NotFound("CONTRACT_CHANGE_NOT_FOUND","해당 프로젝트의 계약 변경을 찾을 수 없습니다.");long? stageId=null;if(input.WorkStageId.HasValue)stageId=await db.InteriorWorkStages.Where(x=>x.PublicId==input.WorkStageId&&x.InteriorProjectId==project.Id).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token)??throw NotFound("WORK_STAGE_NOT_FOUND","해당 프로젝트의 공정을 찾을 수 없습니다.");dispute.InteriorProjectId=project.Id;dispute.InteriorContractChangeId=changeId;dispute.InteriorWorkStageId=stageId;dispute.UpdatedAt=DateTime.UtcNow;dispute.UpdatedByUserId=user;await db.SaveChangesAsync(token)