    public async Task<InteriorProjectDetail> SubmitProjectCompletion(Guid id,SubmitInteriorProjectCompletionRequest input,ClaimsPrincipal principal,CancellationToken token){var identity=await Identity(principal,token);if(!identity.ProviderProfileId.HasValue)throw NotFound("INTERIOR_PROJECT_NOT_FOUND","프로젝트를 찾을 수 없습니다.");var project=await Project(id,token);var assigned=project.SelectedContractorProviderId==identity.ProviderProfileId||await ActiveParticipant(project.Id,identity.ProviderProfileId.Value,"PRIMARY_CONTRACTOR",token);if(!assigned)throw NotFound("INTERIOR_PROJECT_NOT_FOUND","담당 프로젝트를 찾을 수 없습니다.");if(project.StatusCode is "COMPLETED" or "CANCELLED")throw Conflict("INTERIOR_PROJECT_COMPLETION_INVALID","완료보고할 수 없는 프로젝트입니다.");if(await db.InteriorProjectEvents.AnyAsync(x=>x.IdempotencyKey==input.IdempotencyKey,token))return await DetailById(project.Id,token);ApplyVersion(project,input.RowVersion);var stages=await db.InteriorWorkStages.Where(x=>x.InteriorProjectId==project.Id).ToListAsync(token);if(stages.Any(x=>x.StatusCode!="COMPLETED"||x.ProgressPercent!=100))throw Conflict("INTERIOR_WORK_STAGES_INCOMPLETE","등록한 공정은 모두 완료한 뒤 완료보고해 주세요.");var now=DateTime.UtcNow;project.ProviderCompletionSubmittedAt=now;project.ProviderCompletionSubmittedByUserId=identity.UserId;project.ProviderCompletionSummary=input.CompletionSummary.Trim();project.ProviderFinalChecklistJson=Clean(input.FinalChecklistJson);project.StatusCode="INSPECTION";project.UpdatedAt=now;project.UpdatedByUserId=identity.UserId;await db.SaveChangesAsync(token);await Record(project,"PROVIDER_COMPLETION_SUBMITTED",input.IdempotencyKey,identity.UserId,new{project.ProviderCompletionSubmittedAt,workflow=stages.Count==0?"SIMPLE":"STAGED"},token);AuditCommand(identity.UserId,RoleCodes.Provider,"INTERIOR_PROVIDER_COMPLETION_SUBMITTED",project.PublicId,new{project.ProviderCompletionSubmittedAt});await db.SaveChangesAsync(token);return await DetailById(project.Id,token);}

    public async Task<InteriorProjectDetail> CompleteProject(Guid id,CompleteInteriorProjectRequest input,Guid actor,CancellationToken token){var user=await UserId(actor,token);var project=await Project(id,token);if(await db.InteriorProjectEvents.AnyAsync(x=>x.IdempotencyKey==input.IdempotencyKey,token))return await DetailById(project.Id,token);ApplyVersion(project,input.RowVersion);if(!project.ProviderCompletionSubmittedAt.HasValue)throw Conflict("INTERIOR_PROVIDER_COMPLETION_REQUIRED","주 시공 전문가 완료보고가 필요합니다.");if(!project.CustomerCompletionAcknowledgedAt.HasValue)throw Conflict("INTERIOR_CUSTOMER_COMPLETION_REQUIRED","고객 완료확인이 필요합니다.");var stages=await db.InteriorWorkStages.Where(x=>x.InteriorProjectId==project.Id).OrderBy(x=>x.SequenceNo).ToListAsync(token);if(stages.Count==0||stages.Any(x=>x.StatusCode!="COMPLETED"||x.ProgressPercent!=100))throw Conflict("INTERIOR_WORK_STAGES_INCOMPLETE","모든 필수 공정이 완료되어야 합니다.");var finalStage=stages[^1];if(!await db.InteriorStageInspections.AnyAsync(x=>x.WorkStageId==finalStage.Id&&x.InspectionStatusCode=="PASSED",token))throw Conflict("INTERIOR_FINAL_INSPECTION_REQUIRED","필수 최종검사가 완료되어야 합니다.");var now=DateTime.UtcNow;project.StatusCode="COMPLETED";project.ActualCompletionDate=DateOnly.FromDateTime(now);project.AdminCompletedAt=now;project.AdminCompletedByUserId=user;project.UpdatedAt=now;project.UpdatedByUserId=user;var contract=await db.InteriorContracts.AsNoTracking().Where(x=>x.InteriorProjectId==project.Id).OrderByDescending(x=>x.ContractVersion).FirstOrDefaultAsync(token);var provider=contract==null?null:await db.ProviderProfiles.AsNoTracking().SingleAsync(x=>x.Id==contract.ProviderProfileId,token);var category=await db.ServiceCategories.AsNoTracking().SingleAsync(x=>x.Id==project.ServiceCategoryId,token);var key=$"interior-completed:{project.PublicId:N}";if(!await db.ServiceHistoryEntries.AnyAsync(x=>x.IdempotencyKey==key,token))db.ServiceHistoryEntries.Add(new(){CustomerProfileId=project.CustomerProfileId,InteriorProjectId=project.Id,EventTypeCode="INTERIOR_COMPLETED",Title="인테리어 공사 완료",Summary=input.CompletionSummary,ProviderNameSnapshot=provider?.BusinessName,CategoryNameSnapshot=category.Name,TotalAmountSnapshot=contract?.ContractAmount,CurrencyCode=contract?.CurrencyCode,CompletedAtSnapshot=now,SnapshotJson=JsonSerializer.Serialize(new{projectId=project.PublicId,contractVersion=contract?.ContractVersion,contractAmount=contract?.ContractAmount,finalChecklist=input.FinalChecklistJson,stages=stages.Select(x=>new{x.StageName,x.ProgressPercent,x.StatusCode})}),OccurredAt=now,IdempotencyKey=key,CreatedAt=now,CreatedByUserId=user});foreach(var participant in await db.InteriorProjectParticipants.Where(x=>x.InteriorProjectId==project.Id&&x.StatusCode=="ACTIVE"&&x.RoleCode!="AFTER_SERVICE").ToListAsync(token)){participant.StatusCode="ENDED";participant.EffectiveTo??=now;participant.UpdatedAt=now;participant.UpdatedByUserId=user;}await db.SaveChangesAsync(token);await Record(project,"ADMIN_PROJECT_COMPLETED",input.IdempotencyKey,user,new{completedAt=now},token);await Audit(user,"INTERIOR_PROJECT_COMPLETED",project.PublicId,null,new{project.StatusCode},token);return await DetailById(project.Id,token);}

    public async Task<ProviderSiteVisitPrivateResponse> ProviderSiteVisit(Guid id,ClaimsPrincipal principal,CancellationToken token){var identity=await Identity(principal,token);if(!identity.ProviderProfileId.HasValue)throw NotFound("SITE_VISIT_NOT_FOUND","실측 일정을 찾을 수 없습니다.");var row=await(from visit in db.InteriorSiteVisits.AsNoTracking() join project in db.InteriorProjects.AsNoTracking() on visit.InteriorProjectId equals project.Id join request in db.ServiceRequests.AsNoTracking() on project.ServiceRequestId equals request.Id join customer in db.CustomerProfiles.AsNoTracking() on project.CustomerProfileId equals customer.Id join user in db.Users.AsNoTracking() on customer.UserId equals user.Id join area in db.AdministrativeAreas.AsNoTracking() on request.AdministrativeAreaId equals area.Id where visit.PublicId==id&&visit.ProviderProfileId==identity.ProviderProfileId&&project.SelectedSiteVisitProviderId==identity.ProviderProfileId&&visit.StatusCode=="CONFIRMED"&&project.StatusCode!="COMPLETED"&&project.StatusCode!="CANCELLED" select new{visit,project,customer,user,area,request}).SingleOrDefaultAsync(token)??throw NotFound("SITE_VISIT_NOT_FOUND","진행 중인 실측 업무를 찾을 수 없습니다.");var allowed=privacyContract.Decide(PrivacyAudience.AssignedProvider,PrivacyField.Phone,true).CanAccess&&privacyContract.Decide(PrivacyAudience.AssignedProvider,PrivacyField.DetailAddress,true).CanAccess;if(!allowed)throw NotFound("SITE_VISIT_CONTACT_NOT_AVAILABLE","실측 업무 연락처를 조회할 수 없습니다.");return new(row.visit.PublicId,row.project.PublicId,row.customer.DisplayName,row.user.Phone,row.area.AreaName,row.request.DetailAddress,row.visit.ScheduledStartAt,row.visit.ScheduledEndAt,row.visit.AccessConditionText,row.visit.StatusCode);}

    public async Task<ProviderInteriorProjectPrivateResponse> ProviderProjectContact(Guid id,ClaimsPrincipal principal,CancellationToken token){var identity=await Identity(principal,token);if(!identity.ProviderProfileId.HasValue)throw NotFound("INTERIOR_PROJECT_NOT_FOUND","프로젝트를 찾을 수 없습니다.");var row=await(from project in db.InteriorProjects.AsNoTracking()join request in db.ServiceRequests.AsNoTracking()on project.ServiceRequestId equals request.Id join customer in db.CustomerProfiles.AsNoTracking()on project.CustomerProfileId equals customer.Id join user in db.Users.AsNoTracking()on customer.UserId equals user.Id join area in db.AdministrativeAreas.AsNoTracking()on request.AdministrativeAreaId equals area.Id where project.PublicId==id select new{project,request,customer,user,area}).SingleOrDefaultAsync(token)??throw NotFound("INTERIOR_PROJECT_NOT_FOUND","프로젝트를 찾을 수 없습니다.");var active=row.project.StatusCode is "ESTIMATE_READY" or "CONTRACT_PENDING" or "CONTRACTED" or "CONSTRUCTION" or "INSPECTION";var participant=await db.InteriorProjectParticipants.AsNoTracking().Where(x=>x.InteriorProjectId==row.project.Id&&x.ProviderProfileId==identity.ProviderProfileId&&x.RoleCode=="PRIMARY_CONTRACTOR"&&x.StatusCode=="ACTIVE"&&(x.EffectiveTo==null||x.EffectiveTo>DateTime.UtcNow)).FirstOrDefaultAsync(token);var compatible=row.project.SelectedContractorProviderId==identity.ProviderProfileId;if(!active||!compatible||participant is null)throw NotFound("INTERIOR_PROJECT_CONTACT_NOT_AVAILABLE","현재 수행 중인 주 시공 프로젝트 연락처만 조회할 수 있습니다.");var allowed=privacyContract.Decide(PrivacyAudience.AssignedProvider,PrivacyField.Phone,true).CanAccess&&privacyContract.Decide(PrivacyAudience.AssignedProvider,PrivacyField.DetailAddress,true).CanAccess;if(!allowed)throw NotFound("INTERIOR_PROJECT_CONTACT_NOT_AVAILABLE","프로젝트 연락처를 조회할 수 없습니다.");return new(row.project.PublicId,row.customer.DisplayName,row.user.Phone,row.area.AreaName,row.request.DetailAddress,row.project.StatusCode,"PRIMARY_CONTRACTOR",participant.EffectiveFrom,participant.EffectiveTo);}

    private async Task<InteriorProjectDetail> DetailById(long id,CancellationToken token){var row=await(from p in db.InteriorProjects.AsNoTracking() join r in db.ServiceRequests.AsNoTracking() on p.ServiceRequestId equals r.Id join c in db.CustomerProfiles.AsNoTracking() on p.CustomerProfileId equals c.Id join u in db.Users.AsNoTracking() on c.UserId equals u.Id join s in db.ServiceCategories.AsNoTracking() on p.ServiceCategoryId equals s.Id join a in db.AdministrativeAreas.AsNoTracking() on r.AdministrativeAreaId equals a.Id where p.Id==id select new{p,r,c,u,s,a}).SingleAsync(token);var providers=await db.ProviderProfiles.AsNoTracking().Where(x=>x.Id==row.p.SelectedSiteVisitProviderId||x.Id==row.p.SelectedContractorProviderId).ToDictionaryAsync(x=>x.Id,x=>x.BusinessName,token);var selectedQuote=await db.QuoteRevisions.AsNoTracking().Where(x=>x.Id==row.p.CurrentQuoteRevisionId).Select(x=>new{x.PublicId,x.RevisionNo}).SingleOrDefaultAsync(token);var visits=await(from v in db.InteriorSiteVisits.AsNoTracking() join p in db.ProviderProfiles.AsNoTracking() on v.ProviderProfileId equals p.Id where v.InteriorProjectId==id orderby v.ScheduledStartAt select new InteriorSiteVisitResponse(v.PublicId,p.PublicId,p.BusinessName,v.StatusCode,v.ScheduledStartAt,v.ScheduledEndAt,v.ConfirmedAt,v.CompletedAt,v.MeasurementSummaryText,Convert.ToBase64String(v.RowVersion))).ToListAsync(token);var designs=await db.InteriorDesignVersions.AsNoTracking().Where(x=>x.InteriorProjectId==id).OrderBy(x=>x.VersionNo).Select(x=>new InteriorDesignResponse(x.PublicId,x.VersionNo,x.Title,x.Description,x.StatusCode,x.CustomerApprovedAt)).ToListAsync(token);var contractsRows=await(from c in db.InteriorContracts.AsNoTracking() join p in db.ProviderProfiles.AsNoTracking() on c.ProviderProfileId equals p.Id where c.InteriorProjectId==id orderby c.ContractVersion select new{c,p.BusinessName}).ToListAsync(token);var contracts=contractsRows.Select(x=>Contract(x.c,x.BusinessName)).ToArray();var contractIds=contractsRows.Select(x=>x.c.Id).ToArray();var plans=await db.InteriorPaymentPlans.AsNoTracking().Where(x=>contractIds.Contains(x.InteriorContractId)).OrderBy(x=>x.SequenceNo).Select(x=>new InteriorPaymentPlanResponse(x.PublicId,x.SequenceNo,x.PaymentName,x.PlannedAmount,x.PlannedDueDate,x.StatusCode,db.InteriorPaymentConfirmations.Count(c=>c.PaymentPlanId==x.Id))).ToListAsync(token);var stages=await db.InteriorWorkStages.AsNoTracking().Where(x=>x.InteriorProjectId==id).OrderBy(x=>x.SequenceNo).Select(x=>new InteriorWorkStageResponse(x.PublicId,x.SequenceNo,x.StageName,x.StatusCode,x.ProgressPercent,x.PlannedStartDate,x.PlannedEndDate,db.InteriorWorkUpdates.Count(u=>u.WorkStageId==x.Id),db.InteriorStageInspections.Count(i=>i.WorkStageId==x.Id),Convert.ToBase64String(x.RowVersion))).ToListAsync(token);var changes=await db.InteriorContractChanges.AsNoTracking().Where(x=>contractIds.Contains(x.InteriorContractId)).OrderBy(x=>x.ChangeNo).Select(x=>new InteriorChangeResponse(x.PublicId,x.ChangeNo,x.StatusCode,x.ReasonText,x.ScopeChangeText,x.AmountDelta,x.ScheduleImpactDays,x.RequestedAt,x.CustomerDecidedAt,Convert.ToBase64String(x.RowVersion))).ToListAsync(token);var events=await db.InteriorProjectEvents.AsNoTracking().Where(x=>x.InteriorProjectId==id).OrderByDescending(x=>x.OccurredAt).Select(x=>new InteriorEventResponse(x.PublicId,x.EventTypeCode,x.OccurredAt,x.EventDataJson)).ToListAsync(token);return new(row.p.PublicId,Number(row.p.PublicId),row.p.StatusCode,row.p.FeeAssessmentStatusCode,row.r.PublicId,row.c.DisplayName,row.u.Phone,row.s.Name,row.a.AreaName,row.r.DetailAddress,row.p.SelectedSiteVisitProviderId.HasValue?providers.GetValueOrDefault(row.p.SelectedSiteVisitProviderId.Value):null,row.p.SelectedContractorProviderId.HasValue?providers.GetValueOrDefault(row.p.SelectedContractorProviderId.Value):null,selectedQuote?.PublicId,selectedQuote?.RevisionNo,row.p.ContractorSelectedAt,row.p.SiteVisitProviderTrustScoreSnapshot,row.p.ContractorTrustScoreSnapshot,row.p.ProjectStartDate,row.p.ExpectedCompletionDate,row.p.ActualCompletionDate,Convert.ToBase64String(row.p.RowVersion),visits,designs,contracts,plans,stages,changes,events);}
    private async Task LinkFiles(IReadOnlyList<Guid>? ids,long visitId,string purpose,long user,CancellationToken token){var files=await Files(ids,token);var now=DateTime.UtcNow;var order=0;foreach(var file in files)db.InteriorSiteVisitFiles.Add(new(){SiteVisitId=visitId,FileId=file.Id,PurposeCode=purpose,DisplayOrder=order++,CreatedAt=now,CreatedByUserId=user});}
    private async Task<List<StoredFile>> Files(IReadOnlyList<Guid>? ids,CancellationToken token){if(ids is null||ids.Count==0)return[];var unique=ids.Distinct().ToArray();var files=await db.Files.Where(x=>unique.Contains(x.PublicId)&&x.StatusCode=="ACTIVE").ToListAsync(token);if(files.Count!=unique.Length)throw NotFound("FILE_NOT_FOUND","활성 상태인 파일만 연결할 수 있습니다.");return files;}
    private async Task Record(InteriorProject project,string type,string key,long? user,object data,CancellationToken token){if(await db.InteriorProjectEvents.AnyAsync(x=>x.IdempotencyKey==key,token))return;var now=DateTime.UtcNow;db.InteriorProjectEvents.Add(new(){InteriorProjectId=project.Id,EventTypeCode=type,ActorUserId=user,IdempotencyKey=key,EventDataJson=JsonSerializer.Serialize(data),OccurredAt=now,CreatedAt=now});if(await db.NotificationTemplates.AsNoTracking().AnyAsync(x=>x.EventTypeCode==type&&x.IsActive,token))db.OutboxEvents.Add(new(){AggregateType="InteriorProject",AggregatePublicId=project.PublicId,EventType=type,PayloadJson=JsonSerializer.Serialize(data),StatusCode="PENDING",OccurredAt=now,AvailableAt=now,IdempotencyKey="interior-outbox:"+key,CreatedByUserId=user});await db.SaveChangesAsync(token);}
    private async Task Audit(long user,string action,Guid id,object? before,object? after,CancellationToken token){db.AuditLogs.Add(new(){OccurredAt=DateTime.UtcNow,ActorUserId=user,ActorRoleCode="ADMIN",ActionCode=action,EntityType="InteriorProject",EntityPublicId=id,BeforeJson=before==null?null:JsonSerializer.Serialize(before),AfterJson=after==null?null:JsonSerializer.Serialize(after)});await db.SaveChangesAsync(token);}
    private void AuditCommand(long user,string role,string action,Guid id,object after)=>db.AuditLogs.Add(new(){OccurredAt=DateTime.UtcNow,ActorUserId=user,ActorRoleCode=role,ActionCode=action,EntityType="InteriorProject",EntityPublicId=id,ResultCode="SUCCESS",AfterJson=JsonSerializer.Serialize(after)});
    private async Task EnsureParticipant(InteriorProject project,long provider,string role,bool primary,string scope,long actor,DateTime now,CancellationToken token){if(await db.InteriorProjectParticipants.AnyAsync(x=>x.InteriorProjectId==project.Id&&x.ProviderProfileId==provider&&x.RoleCode==role,token))return;db.InteriorProjectParticipants.Add(new(){InteriorProjectId=project.Id,ProviderProfileId=provider,RoleCode=role,EffectiveFrom=now,StatusCode="ACTIVE",IsPrimary=primary,ScopeText=scope,CreatedAt=now,CreatedByUserId=actor,UpdatedAt=now,UpdatedByUserId=actor});}
    private Task<bool> ActiveParticipant(long project,long provider,string role,CancellationToken token)=>db.InteriorProjectParticipants.AsNoTracking().AnyAsync(x=>x.InteriorProjectId==project&&x.ProviderProfileId==provider&&x.RoleCode==role&&x.StatusCode=="ACTIVE"&&(x.EffectiveTo==null||x.EffectiveTo>DateTime.UtcNow),token);
    private static InteriorParticipantResponse Participant(InteriorProjectParticipant x,ProviderProfile provider)=>new(x.PublicId,provider.PublicId,provider.BusinessName,x.RoleCode,x.EffectiveFrom,x.EffectiveTo,x.StatusCode,x.IsPrimary,x.ScopeText,Version(x.RowVersion));
    private static string Role(string value){var role=value.Trim().ToUpperInvariant();if(role is not("SITE_SURVEY" or "DESIGN" or "PRIMARY_CONTRACTOR" or "TRADE_CONTRACTOR" or "INSPECTION" or "AFTER_SERVICE"))throw Conflict("INTERIOR_PARTICIPANT_ROLE_INVALID","지원하지 않는 인테리어 참여 역할입니다.");return role;}
    private void ApplyVersion(object entity,string? value){if(!string.IsNullOrWhiteSpace(value))db.Entry(entity).Property("RowVersion").OriginalValue=Convert.FromBase64String(value);}
    private async Task<InteriorProject> Project(Guid id,CancellationToken token)=>await db.InteriorProjects.SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw NotFound("INTERIOR_PROJECT_NOT_FOUND","인테리어 프로젝트를 찾을 수 없습니다.");
    private async Task<long> UserId(Guid id,CancellationToken token)=>await db.Users.Where(x=>x.PublicId==id&&x.StatusCode=="ACTIVE").Select(x=>x.Id).SingleAsync(token);
    private async Task<decimal?> CurrentTrust(long provider,CancellationToken token)=>await db.ProviderTrustScoreCurrent.AsNoTracking().Where(x=>x.ProviderProfileId==provider&&x.EvaluationStatusCode=="CALCULATED").Select(x=>(decimal?)x.Score).SingleOrDefaultAsync(token);
    private async Task<IdentityValue> Identity(ClaimsPrincipal p,CancellationToken token){if(!Guid.TryParse(p.FindFirstValue(ClaimTypes.NameIdentifier),out var id))throw new InteriorBusinessException(401,"AUTHENTICATION_REQUIRED","로그인이 필요합니다.");return await db.Users.AsNoTracking().Where(x=>x.PublicId==id&&x.StatusCode=="ACTIVE").Select(x=>new IdentityValue(x.Id,db.CustomerProfiles.Where(c=>c.UserId==x.Id).Select(c=>(long?)c.Id).FirstOrDefault(),db.ProviderProfiles.Where(v=>v.UserId==x.Id).Select(v=>(long?)v.Id).FirstOrDefault())).SingleAsync(token);}
    private static InteriorSiteVisitResponse Visit(InteriorSiteVisit x,Guid providerId,string name)=>new(x.PublicId,providerId,name,x.StatusCode,x.ScheduledStartAt,x.ScheduledEndAt,x.ConfirmedAt,x.CompletedAt,x.MeasurementSummaryText,Convert.ToBase64String(x.RowVersion));
    private static InteriorContractResponse Contract(InteriorContract x,string name)=>new(x.PublicId,x.ContractVersion,name,x.StatusCode,x.ContractAmount,x.CurrencyCode,x.PlannedStartDate,x.PlannedCompletionDate,x.CustomerAgreedAt,x.ProviderAgreedAt,x.EffectiveAt,Convert.ToBase64String(x.RowVersion));
    private static InteriorWorkStageResponse Stage(InteriorWorkStage x,int updates,int inspections)=>new(x.PublicId,x.SequenceNo,x.StageName,x.StatusCode,x.ProgressPercent,x.PlannedStartDate,x.PlannedEndDate,updates,inspections,Convert.ToBase64String(x.RowVersion));
    private static InteriorChangeResponse Change(InteriorContractChange x)=>new(x.PublicId,x.ChangeNo,x.StatusCode,x.ReasonText,x.ScopeChangeText,x.AmountDelta,x.ScheduleImpactDays,x.RequestedAt,x.CustomerDecidedAt,Convert.ToBase64String(x.RowVersion));
    private static string Version(byte[] value)=>value.Length==0?string.Empty:Convert.ToBase64String(value);
    private static string? Clean(string? value)=>string.IsNullOrWhiteSpace(value)?null:value.Trim();
    private static string Number(Guid id)=>"IP-"+id.ToString("N")[..10].ToUpperInvariant();
    private static InteriorBusinessException NotFound(string code,string message)=>new(404,code,message);private static InteriorBusinessException Conflict(string code,string message)=>new(409,code,message);
    private sealed record IdentityValue(long UserId,long? CustomerProfileId,long? ProviderProfileId);
}
